-- Add round_type to routes so the checklist knows to show dry vs wet food
alter table public.routes
  add column round_type text not null default 'evening'
    check (round_type in ('morning', 'evening'));

-- Replace single evening route with morning + evening, both covering all 11 stations
delete from public.route_stations;
delete from public.routes;


